/usr/bin/bash -lc "command -v bfconvert || true
find /opt/Fiji.app -maxdepth 3 -type f \\( -iname '*bio*format*.jar' -o -iname '*formats*.jar' \\) -printf '%p\\n' | head -30
python - <<'PY'
mods=['readlif','aicsimageio','bioio','javabridge','imagej','roifile','czifile']
for m in mods:
 try:
  x=__import__(m); print(m,'OK',getattr(x,'__version__',''))
 except Exception as e: print(m,'NO',type(e).__name__)
PY"

