import numpy as np, cv2
mov=np.load('/tmp/movie_c0.npy').astype(np.float32)[849:1457,537:1145]
st=np.load('/tmp/stain_c0.npy').astype(np.float32)[952:1560,565:1173]
A=np.array([[1.00010247,-.0295428294,29.7168608],[.0295428294,1.00010247,-7.46943972]],np.float32) # stain -> movie
def invaff(a): return cv2.invertAffineTransform(a)
for kind in ['raw','norm','log','grad','hp']:
 def prep(a):
  if kind=='raw':
   lo,hi=np.percentile(a,[2,98]); return np.clip((a-lo)/(hi-lo),0,1).astype(np.float32)
  if kind=='norm':
   a=cv2.normalize(a,None,0,1,cv2.NORM_MINMAX); return cv2.GaussianBlur(a,(0,0),2)
  if kind=='log':
   a=np.log1p(a-a.min()); return cv2.normalize(a,None,0,1,cv2.NORM_MINMAX)
  if kind=='grad':
   a=cv2.GaussianBlur(a,(0,0),1.5); gx=cv2.Sobel(a,cv2.CV_32F,1,0); gy=cv2.Sobel(a,cv2.CV_32F,0,1); a=cv2.magnitude(gx,gy); return cv2.normalize(a,None,0,1,cv2.NORM_MINMAX)
  lo,hi=np.percentile(a,[2,98]); a=np.clip((a-lo)/(hi-lo),0,1); return (cv2.GaussianBlur(a,(0,0),1)-cv2.GaussianBlur(a,(0,0),15)).astype(np.float32)
 M,S=prep(mov),prep(st)
 for motion in [cv2.MOTION_EUCLIDEAN,cv2.MOTION_AFFINE]:
  W=invaff(A)
  if motion==cv2.MOTION_EUCLIDEAN:
   # project inverse into rigid
   ang=np.arctan2(W[1,0],W[0,0]); W[:2,:2]=[[np.cos(ang),-np.sin(ang)],[np.sin(ang),np.cos(ang)]]
  try:
   cc,W=cv2.findTransformECC(M,S,W,motion,(cv2.TERM_CRITERIA_EPS|cv2.TERM_CRITERIA_COUNT,3000,1e-9),None,5)
   print(kind,motion,'cc',cc,'W M->S',W,'inv S->M',invaff(W))
  except Exception as e: print(kind,motion,'FAIL',str(e).splitlines()[0])
